rule sigma 'possible_c2_beaconing' {
  meta:
    description = 'Possible C2 beaconing at 30-second intervals'
  condition:
    process_name == 'rundll32.exe' and process_entropy > 0.5
}

rule sigma 'possible_c2_beaconing' {
  meta:
    description = 'Possible C2 beaconing at 30-second intervals'
