rule yara 'possible_c2_beaconing' {
  meta:
    description = 'Possible C2 beaconing at 30-second intervals'
  strings:
    $beacon = "C2 beaconing" {
      condition: (regmatch(ascii, 0x00) == 1) and (regmatch(ascii, 0x01) == 1)
    }
  condition:
    $beacon {
      condition: (regmatch(ascii, 0x00) == 1) and (regmatch(ascii, 0x01) == 1)
    }
}

